use corpse_core::{startup,generation};
fn main(){for seed in [format!("{}-56","x".repeat(256)),"qa-mixed-33cdd108d7485523".into(),"生成-é-🌱-115".into(),"qa-mixed-3faf6c43aaa5d7eb".into()]{let mut r=startup::new_run_shell_revision(&seed,"Unblessed",false,37.).unwrap();let result=startup::ensure_floors_with(&mut r,40,&|d,s,u| {let f=generation::generate_floor_full_revision(d,s,u,37.)?;if let Some(e)=f.godbeast_event.as_ref(){if let Some(t)=e.tap.as_ref(){let at=t.y as usize*f.width()+t.x as usize;println!("seed={seed} depth={d} godbeast={} tap=({}, {}) tile={}",e.kind,t.x,t.y,f.tiles[at]);}}Ok(f)});println!("seed={seed} result={result:?} retained={}",r.floors.len());}}
